      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 100)).toBe(
        1200,
      );
    });

    it("uses overflowCostCents when set and weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 3000, 1)], 100),
      ).toBe(1500);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket (500g)
      expect(unsorted.computeShippingCents([makeLine("a", 400, 1)], 100)).toBe(
        300,
      );
    });

    it("accumulates weight across multiple lines", () => {
      // 300*2 + 200*3 = 1200g → second bracket (up to 2000)
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 3)];
      expect(calc.computeShippingCents(lines, 100)).toBe(700);
    });
  });
});

