describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = cartWithItems();
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });
  });

  describe("inventoryChecker", () => {
    it("proceeds when all items are available", async () => {
      const cart = cartWithItems();
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available but insufficient)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("a");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax provider for tax calculation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(0),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 2); // subtotal = 2000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(200); // 10% of 2000
      expect(result.totals.shippingCents).toBe(500);
      // total = 2000 + 200 + 500 = 2700
      expect(result.totals.totalCents).toBe(2700);
    });

    it("applies discount before async tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 2); // subtotal = 2000, discount = 500, taxable = 1500

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150); // 10% of 1500
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("combined collaborators", () => {
    it("uses priceFetcher, inventoryChecker, and asyncTaxProvider together", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(productA, 1); // original price 1000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(800),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Price refreshed to 800
      expect(result.lines[0]!.product.unitPriceCents).toBe(800);
      expect(result.totals.subtotalCents).toBe(800);
      // tax = 5% of 800 = 40
      expect(result.totals.taxCents).toBe(40);
      // inventory was checked
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 1);
    });

    it("does not modify the original cart state", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      await cart.checkout({ priceFetcher });

      // Original cart unaffected
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("applies 10% to 1000 cents → 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down fractional cents (15% of 999 = 149.85 → 149)", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotal", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(1_000_000)).toBe(250_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when equal to discount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sum can exceed subtotal (Cart clamps it)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // 80% of 1000 + 500 = 1300 (exceeds 1000, but sum mode doesn't clamp)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      // total discount = 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const fixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off 1000, remaining 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );

      const percentFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );

      expect(fixedFirst.computeDiscountCents(1000)).toBe(280);
      expect(percentFirst.computeDiscountCents(1000)).toBe(300);
    });

    it("chain never exceeds subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // 600 from first, remaining 400, min(600,400)=400 from second → total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

