import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type InventoryChecker, type PriceFetcher } from "../src/inventory.ts";
import type { AsyncTaxRateProvider, TaxCalculator } from "../src/tax.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

// ─── helpers ────────────────────────────────────────────────────────

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

function cartWithItems(config: ConstructorParameters<typeof Cart>[0] = {}): Cart {
  const cart = new Cart(config);
  cart.add(productA, 2); // 2000
  cart.add(productB, 1); // 2000
  return cart;
}

// ─── Cart line management ───────────────────────────────────────────

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(productA, 1);
      expect(cart.itemCount).toBe(1);
    });

    it("merges quantity when adding the same product twice", () => {
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects zero quantity", () => {
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects product with negative unitPriceCents", () => {
      const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      cart.add(productA, 1);
      expect(cart.remove(productA.id)).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(productA, 2);
      cart.updateQuantity(productA.id, 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(productA, 2);
      cart.updateQuantity(productA.id, 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove(productA.id)).toBe(false);
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity(productA.id, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity(productA.id, 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy — mutation does not affect cart", () => {
      cart.add(productA, 1);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(1);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});

// ─── Cart pricing pipeline ─────────────────────────────────────────

describe("Cart pricing pipeline", () => {
  it("computes correct totals with default policies (empty cart)", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = cartWithItems();
    // 1000*2 + 2000*1 = 4000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(300),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = cartWithItems({ discountPolicy, taxCalculator, shippingCalculator });
    const totals = cart.totals();

    // subtotal = 4000, discount = 1000, discountedSubtotal = 3000
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(4000);
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(3000, "US");
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      3000,
    );

    expect(totals.subtotalCents).toBe(4000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(300);
    expect(totals.shippingCents).toBe(500);
    // total = 3000 + 300 + 500 = 3800
    expect(totals.totalCents).toBe(3800);
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = cartWithItems({ discountPolicy });
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal] — over-subtotal discount capped", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = cartWithItems({ discountPolicy });
    const totals = cart.totals();
    expect(totals.discountCents).toBe(4000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = cartWithItems({ taxCalculator });
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = cartWithItems({ shippingCalculator });
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses custom region for tax calculation", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

// ─── Cart.checkout() ────────────────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = cartWithItems();
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
