function cartWithItems(config: ConstructorParameters<typeof Cart>[0] = {}): Cart {
  const cart = new Cart(config);
  cart.add(productA, 2); // 2000
  cart.add(productB, 1); // 2000
  return cart;
}

// ─── Cart line management ───────────────────────────────────────────

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(productA, 1);
      expect(cart.itemCount).toBe(1);
    });

    it("merges quantity when adding the same product twice", () => {
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects zero quantity", () => {
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects product with negative unitPriceCents", () => {
      const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      cart.add(productA, 1);
      expect(cart.remove(productA.id)).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(productA, 2);
      cart.updateQuantity(productA.id, 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(productA, 2);
      cart.updateQuantity(productA.id, 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove(productA.id)).toBe(false);
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity(productA.id, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(productA, 1);
      expect(() => cart.updateQuantity(productA.id, 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy — mutation does not affect cart", () => {
      cart.add(productA, 1);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(1);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});

// ─── Cart pricing pipeline ─────────────────────────────────────────

describe("Cart pricing pipeline", () => {
  it("computes correct totals with default policies (empty cart)", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = cartWithItems();
    // 1000*2 + 2000*1 = 4000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(300),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = cartWithItems({ discountPolicy, taxCalculator, shippingCalculator });
    const totals = cart.totals();

    // subtotal = 4000, discount = 1000, discountedSubtotal = 3000
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(4000);
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(3000, "US");
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      3000,
    );

    expect(totals.subtotalCents).toBe(4000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(300);
    expect(totals.shippingCents).toBe(500);
    // total = 3000 + 300 + 500 = 3800
    expect(totals.totalCents).toBe(3800);
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = cartWithItems({ discountPolicy });
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal] — over-subtotal discount capped", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = cartWithItems({ discountPolicy });
    const totals = cart.totals();
    expect(totals.discountCents).toBe(4000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = cartWithItems({ taxCalculator });
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = cartWithItems({ shippingCalculator });
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses custom region for tax calculation", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

// ─── Cart.checkout() ────────────────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = cartWithItems();
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });
  });

  describe("inventoryChecker", () => {
    it("proceeds when all items are available", async () => {
      const cart = cartWithItems();
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available but insufficient)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("uses default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("a");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax provider for tax calculation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(0),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 2); // subtotal = 2000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(200); // 10% of 2000
      expect(result.totals.shippingCents).toBe(500);
      // total = 2000 + 200 + 500 = 2700
      expect(result.totals.totalCents).toBe(2700);
    });

    it("applies discount before async tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 2); // subtotal = 2000, discount = 500, taxable = 1500

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150); // 10% of 1500
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("combined collaborators", () => {
    it("uses priceFetcher, inventoryChecker, and asyncTaxProvider together", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(productA, 1); // original price 1000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(800),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Price refreshed to 800
      expect(result.lines[0]!.product.unitPriceCents).toBe(800);
      expect(result.totals.subtotalCents).toBe(800);
      // tax = 5% of 800 = 40
      expect(result.totals.taxCents).toBe(40);
      // inventory was checked
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 1);
    });

    it("does not modify the original cart state", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      await cart.checkout({ priceFetcher });

      // Original cart unaffected
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });
});
"}

