import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

const singleLine: readonly CartLine[] = [makeLine("item", 500, 1)];

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents(singleLine, 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents(singleLine, 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents(singleLine, 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents(singleLine, 7000)).toBe(0);
    });

    it("returns flat fee when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents(singleLine, 4999)).toBe(599);
    });

    it("returns 0 when freeOverCents is 0 (always free)", () => {
      const calc = new FlatShippingCalculator(599, 0);
      expect(calc.computeShippingCents(singleLine, 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 1.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
      const line: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100 },
        quantity: 2,
      };
      expect(calc.computeShippingCents([line], 200)).toBe(0);
    });

    it("selects first bracket when weight <= first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 100)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 250, 2)], 100)).toBe(300);
    });

    it("selects second bracket when weight exceeds first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 100)).toBe(700);
    });

    it("selects third bracket at its boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 100)).toBe(
        1200,
      );
    });

    it("uses heaviest bracket cost when weight overflows and no overflow cost set", () => {
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 100)).toBe(
        1200,
      );
    });

    it("uses overflowCostCents when set and weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 3000, 1)], 100),
      ).toBe(1500);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket (500g)
      expect(unsorted.computeShippingCents([makeLine("a", 400, 1)], 100)).toBe(
        300,
      );
    });

    it("accumulates weight across multiple lines", () => {
      // 300*2 + 200*3 = 1200g → second bracket (up to 2000)
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 3)];
      expect(calc.computeShippingCents(lines, 100)).toBe(700);
    });
  });
});

